import { GoogleGenAI } from '@google/genai';
import markdownit from 'markdown-it';
import { sanitizeHtml } from 'safevalues';
import { setElementInnerHtml } from 'safevalues/dom';

const md = markdownit();

// --- DOM Elements ---
const elementGrid = document.getElementById('element-grid')!;
const networkGrid = document.getElementById('network-grid')!;
const controlsContainer = document.getElementById('controls-container')!;
const synthesizeButton = document.getElementById('synthesize-button') as HTMLButtonElement;
const outputContent = document.getElementById('output-content')!;
const synthesisCore = document.getElementById('synthesis-core')!;

// Visual Panel Elements
const visualizeButton = document.getElementById('visualize-button') as HTMLButtonElement;
const visualOutputContainer = document.getElementById('visual-output-container')!;
const visualOutput = document.getElementById('visual-output')!;

// Fusion Panel Elements
const initiateFusionButton = document.getElementById('initiate-fusion-button') as HTMLButtonElement;
const fusionCore = document.getElementById('fusion-core')!;
const fusionStatus = document.getElementById('fusion-status')!;
const fusionPower = document.getElementById('fusion-power')!;
const fusionOutputContent = document.getElementById('fusion-output-content')!;


// --- Data ---
const DRIVE_FOUNDATIONS = ['Warp Field Coils', 'Graviton Emitter', 'Plasma Injector', 'Subspace Manifold', 'Chroniton Stabilizer', 'Negative Mass Emitter', 'Causality Anchor', 'Spacetime Resonator'];
const SUBSPACE_HARMONICS = ['Interdimensional Phase Shifting', 'Alcubierre Metric Resonance', 'Negative Energy Field', 'Spacetime Compression'];
const PROPERTIES = [
  { id: 'warpStability', name: 'Warp Field Stability', min: 0, max: 100, unit: '%', costMultiplier: 25 },
  { id: 'permeability', name: 'Subspace Permeability', min: 0, max: 100, unit: '%', costMultiplier: 30 },
  { id: 'energyEfficiency', name: 'Energy Efficiency', min: 0, max: 100, unit: '%', costMultiplier: 20 },
  { id: 'ftlVelocity', name: 'FTL Velocity (Warp)', min: 1, max: 9.9, unit: '', costMultiplier: 1000 },
];

let ai: GoogleGenAI;
let lastComponentSpec = '';
let lastComponentProperties: { [key: string]: number } = {};

// --- Helper Functions ---
function updateEstimatedCost() {
  let cost = 1000;
  PROPERTIES.forEach(prop => {
    const slider = document.getElementById(prop.id) as HTMLInputElement;
    if (slider) {
      cost += parseFloat(slider.value) * prop.costMultiplier;
    }
  });
  const display = document.getElementById('cost-display');
  if (display) {
    display.textContent = `Estimated Cost: ${Math.floor(cost).toLocaleString()} Credits`;
  }
}

// --- Initialization ---
function initializeUI() {
  // Create Drive Foundation Checkboxes
  DRIVE_FOUNDATIONS.forEach(element => {
    const label = document.createElement('label');
    label.className = 'element-label';
    label.innerHTML = `
      <input type="checkbox" name="element" value="${element}">
      <span class="custom-checkbox"><span class="tick"></span></span>
      <span>${element}</span>
    `;
    elementGrid.appendChild(label);
  });

  // Create Subspace Harmonic Checkboxes
  SUBSPACE_HARMONICS.forEach(node => {
    const label = document.createElement('label');
    label.className = 'network-node-label';
    label.innerHTML = `
      <input type="checkbox" name="network-node" value="${node}">
      <span class="custom-node"><span class="node-core"></span></span>
      <span>${node}</span>
    `;
    networkGrid.appendChild(label);
  });

  // Create Property Sliders
  PROPERTIES.forEach(prop => {
    const group = document.createElement('div');
    group.className = 'slider-group';
    const defaultValue = prop.id === 'ftlVelocity' ? prop.min : (prop.min + prop.max) / 2;
    group.innerHTML = `
      <div class="label-row">
        <label for="${prop.id}">${prop.name}</label>
        <span class="slider-value" id="${prop.id}-value">${defaultValue}${prop.unit}</span>
      </div>
      <input type="range" id="${prop.id}" name="${prop.id}" min="${prop.min}" max="${prop.max}" value="${defaultValue}" ${prop.id === 'ftlVelocity' ? 'step="0.1"' : ''}>
    `;
    controlsContainer.appendChild(group);

    const slider = group.querySelector<HTMLInputElement>(`#${prop.id}`)!;
    const valueDisplay = group.querySelector<HTMLSpanElement>(`#${prop.id}-value`)!;
    slider.addEventListener('input', () => {
      valueDisplay.textContent = slider.value + prop.unit;
      updateEstimatedCost();
    });
  });

  // Create Cost Display
  const costDisplay = document.createElement('div');
  costDisplay.id = 'cost-display';
  costDisplay.style.cssText = 'margin-top: 1rem; padding: 1rem; background: rgba(0, 0, 0, 0.3); border: 1px solid var(--border-color); border-radius: 8px; text-align: center; color: var(--accent-color); font-weight: 700; text-shadow: 0 0 5px var(--accent-color);';
  controlsContainer.appendChild(costDisplay);

  // Initial Update
  setTimeout(updateEstimatedCost, 0);
}

async function initializeAI() {
  try {
    ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  } catch (error) {
    console.error('Failed to initialize AI:', error);
    setElementInnerHtml(outputContent, sanitizeHtml('<p class="error">Error: Could not initialize AI Engineering Subsystem. Please check configuration.</p>'));
    synthesizeButton.disabled = true;
  }
}

// --- Core Logic ---
function buildPrompt(): string {
  const selectedFoundations = Array.from(document.querySelectorAll<HTMLInputElement>('input[name="element"]:checked'))
                                .map(el => el.value);
  const selectedHarmonics = Array.from(document.querySelectorAll<HTMLInputElement>('input[name="network-node"]:checked'))
                                .map(el => el.value);

  if (selectedFoundations.length === 0) {
    alert('Please select at least one drive foundation.');
    return '';
  }

  const properties: { [key: string]: number } = {};
  let estimatedCost = 1000;

  const propertiesText = PROPERTIES.map(prop => {
    const slider = document.getElementById(prop.id) as HTMLInputElement;
    const value = parseFloat(slider.value);
    properties[prop.id] = value;
    estimatedCost += value * prop.costMultiplier;
    return `- ${prop.name}: ${slider.value}${prop.unit || ''}`;
  }).join('\n');

  lastComponentProperties = properties; // Store for fusion sim

  let prompt = `
    Based on the following parameters, design an advanced subspace drive component.

    **Core Drive Foundations:**
    ${selectedFoundations.join(', ')}
  `;

  if (selectedHarmonics.length > 0) {
    prompt += `
    **Subspace Harmonic Infusion:**
    ${selectedHarmonics.join(', ')}
    `;
  }

  prompt += `
    **Desired Performance Metrics:**
    ${propertiesText}
    - **Estimated Cost:** ${Math.floor(estimatedCost).toLocaleString()} Credits

    Provide a detailed technical specification using Markdown, including:
    1.  **Component Designation:** A creative, technical-sounding name (e.g., "Mark IV Resonant Warp Inductor").
    2.  **Operational Principle:** A brief description of how it works, incorporating the selected foundations and subspace harmonics.
    3.  **Performance Analysis:** A summary of its capabilities based on the desired metrics.
    4.  **Integration Notes & Risks:** Suggest how it integrates into a larger drive system and mention any potential operational risks or exotic side effects.
    5.  **Cost Analysis:** A brief justification for the estimated cost of ${Math.floor(estimatedCost).toLocaleString()} Credits based on the high-performance specifications.
  `;

  return prompt;
}

async function handleSynthesize() {
  const prompt = buildPrompt();
  if (!prompt) return;

  synthesizeButton.disabled = true;
  initiateFusionButton.disabled = true;
  visualizeButton.disabled = true;
  setElementInnerHtml(visualOutput, sanitizeHtml('<p class="placeholder">Design a component to generate a visual blueprint.</p>'));
  synthesisCore.classList.add('synthesizing');
  outputContent.innerHTML = '';
  const placeholder = document.createElement('p');
  placeholder.className = 'placeholder';
  placeholder.textContent = 'Engineering component... Calibrating subspace matrix...';
  outputContent.appendChild(placeholder);

  try {
    const stream = await ai.models.generateContentStream({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: `You are an advanced AI specializing in theoretical FTL propulsion systems. Your purpose is to design subspace drive components based on user-specified parameters. Be creative, scientific, and detailed in your responses. If Subspace Harmonics are specified, treat them as core conceptual drivers for the component's exotic capabilities. Format your output using Markdown.`,
      },
    });

    let fullResponse = '';
    placeholder.remove(); // Remove initial placeholder

    for await (const chunk of stream) {
      fullResponse += chunk.text;
      const renderedHtml = md.render(fullResponse + '▋'); // Add cursor
      setElementInnerHtml(outputContent, sanitizeHtml(renderedHtml));
    }

    // Final render without cursor
    const finalHtml = md.render(fullResponse);
    setElementInnerHtml(outputContent, sanitizeHtml(finalHtml));
    lastComponentSpec = fullResponse; // Store for fusion sim

    analyzeComponentForFusion();
    visualizeButton.disabled = false;

  } catch (error) {
    console.error('Engineering failed:', error);
    const errorHtml = md.render('**Design Failed!**\n\nA cascade failure in the simulation matrix occurred. Please adjust parameters and try again.');
    setElementInnerHtml(outputContent, sanitizeHtml(errorHtml));
    lastComponentSpec = '';
  } finally {
    synthesizeButton.disabled = false;
    synthesisCore.classList.remove('synthesizing');
  }
}

async function handleVisualize() {
  if (!lastComponentSpec) return;

  visualizeButton.disabled = true;
  synthesizeButton.disabled = true;
  visualOutputContainer.classList.add('loading');
  setElementInnerHtml(visualOutput, sanitizeHtml('<p class="placeholder">Generating holographic blueprint...</p>'));

  try {
    const prompt = `A detailed, photorealistic, technical blueprint of the following advanced FTL drive component. Render it as a glowing blue hologram on a dark, minimalist background. Sci-fi aesthetic. Component description: ${lastComponentSpec}`;

    const response = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: prompt,
        config: {
          numberOfImages: 1,
          outputMimeType: 'image/jpeg',
          aspectRatio: '1:1',
        },
    });

    const base64ImageBytes: string = response.generatedImages[0].image.imageBytes;
    const imageUrl = `data:image/jpeg;base64,${base64ImageBytes}`;

    setElementInnerHtml(visualOutput, sanitizeHtml(`<img src="${imageUrl}" alt="Generated component blueprint">`));

  } catch (error) {
    console.error('Visualization failed:', error);
    setElementInnerHtml(visualOutput, sanitizeHtml('<p class="error"><b>Blueprint Generation Failed!</b><br>Quantum interference detected. Please try again or re-engineer.</p>'));
    visualizeButton.disabled = false; // Allow retry on error
  } finally {
    visualOutputContainer.classList.remove('loading');
    synthesizeButton.disabled = false;
  }
}

function analyzeComponentForFusion() {
  const { warpStability, energyEfficiency } = lastComponentProperties;
  if (warpStability >= 75 && energyEfficiency >= 75) {
    initiateFusionButton.disabled = false;
    const placeholder = fusionOutputContent.querySelector('.placeholder');
    if (placeholder) {
      placeholder.textContent = 'Component is fusion-compatible. Ready to initiate simulation.';
    }
  } else {
    initiateFusionButton.disabled = true;
    const placeholder = fusionOutputContent.querySelector('.placeholder');
    if (placeholder) {
      placeholder.textContent = 'Component not suitable for fusion. Requires Warp Stability and Energy Efficiency >= 75%.';
    }
  }
}

function buildFusionPrompt(): string {
  return `
    You are a fusion reactor simulation AI. A new subspace drive component has been designed and is now being tested for its potential in a cold fusion reactor.

    **Component Full Specification:**
    ${lastComponentSpec}

    **Analysis Task:**
    Based on the component's detailed specifications, especially its operational principles and materials, provide a simulation report.
    1.  **Plasma Interaction:** Describe how the component's unique properties (e.g., its handling of spacetime, gravitons, or negative energy) would interact with and contain a high-energy fusion plasma.
    2.  **Reactor Performance:** Estimate the potential power output in Megawatts (MW) and the overall stability of the reaction.
    3.  **Final Verdict:** Conclude with a single-word verdict: 'STABLE', 'UNSTABLE', or 'OPTIMAL'.

    Format the response as a concise, technical report using Markdown.
  `;
}

async function handleFusionSimulation() {
  const prompt = buildFusionPrompt();
  if (!prompt) return;

  initiateFusionButton.disabled = true;
  synthesizeButton.disabled = true;
  fusionCore.classList.add('active');
  fusionStatus.textContent = 'SIMULATING';
  fusionPower.textContent = '... MW';
  fusionOutputContent.innerHTML = '';
  const placeholder = document.createElement('p');
  placeholder.className = 'placeholder';
  placeholder.textContent = 'Initiating plasma containment... Running quantum analysis...';
  fusionOutputContent.appendChild(placeholder);

  try {
    const stream = await ai.models.generateContentStream({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: `You are a sophisticated AI that simulates the performance of theoretical components within a cold fusion reactor. Provide a detailed, scientific, and creative analysis based on the provided component data. Your tone should be that of a lead research engineer reporting findings. Format output using Markdown.`,
      },
    });

    let fullResponse = '';
    placeholder.remove();

    for await (const chunk of stream) {
      fullResponse += chunk.text;
      const renderedHtml = md.render(fullResponse + '▋');
      setElementInnerHtml(fusionOutputContent, sanitizeHtml(renderedHtml));
    }

    const finalHtml = md.render(fullResponse);
    setElementInnerHtml(fusionOutputContent, sanitizeHtml(finalHtml));

    // Update status from response
    if (fullResponse.includes('OPTIMAL')) {
      fusionStatus.textContent = 'OPTIMAL';
    } else if (fullResponse.includes('STABLE')) {
      fusionStatus.textContent = 'STABLE';
    } else {
      fusionStatus.textContent = 'UNSTABLE';
    }
    const powerMatch = fullResponse.match(/(\d+(\.\d+)?)\s*MW/);
    if(powerMatch) {
      fusionPower.textContent = `${powerMatch[1]} MW`;
    } else {
      fusionPower.textContent = 'N/A';
    }


  } catch (error) {
    console.error('Fusion sim failed:', error);
    const errorHtml = md.render('**Simulation Failed!**\n\nContainment field collapsed. Check component specifications.');
    setElementInnerHtml(fusionOutputContent, sanitizeHtml(errorHtml));
    fusionStatus.textContent = 'ERROR';
  } finally {
    fusionCore.classList.remove('active');
    synthesizeButton.disabled = false;
    // Keep fusion button disabled until a new compatible component is made
  }
}

// --- Event Listeners ---
synthesizeButton.addEventListener('click', handleSynthesize);
visualizeButton.addEventListener('click', handleVisualize);
initiateFusionButton.addEventListener('click', handleFusionSimulation);

// --- App Start ---
initializeUI();
initializeAI();

