  visualOutputContainer.classList.add('loading');
  setElementInnerHtml(visualOutput, sanitizeHtml('<p class="placeholder">Generating holographic blueprint...</p>'));

  try {
    const prompt = `A detailed, photorealistic, technical blueprint of the following advanced FTL drive component. Render it as a glowing blue hologram on a dark, minimalist background. Sci-fi aesthetic. Component description: ${lastComponentSpec}`;

    const response = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: prompt,
        config: {
          numberOfImages: 1,
          outputMimeType: 'image/jpeg',
          aspectRatio: '1:1',
        },
    });

    const base64ImageBytes: string = response.generatedImages[0].image.imageBytes;
    const imageUrl = `data:image/jpeg;base64,${base64ImageBytes}`;

    setElementInnerHtml(visualOutput, sanitizeHtml(`<img src="${imageUrl}" alt="Generated component blueprint">`));

  } catch (error) {
    console.error('Visualization failed:', error);
    setElementInnerHtml(visualOutput, sanitizeHtml('<p class="error"><b>Blueprint Generation Failed!</b><br>Quantum interference detected. Please try again or re-engineer.</p>'));
    visualizeButton.disabled = false; // Allow retry on error
  } finally {
    visualOutputContainer.classList.remove('loading');
    synthesizeButton.disabled = false;
  }
}

function analyzeComponentForFusion() {
  const { warpStability, energyEfficiency } = lastComponentProperties;
  // Fallback if properties are missing (e.g. error in parsing)
  if (warpStability === undefined || energyEfficiency === undefined) {
      initiateFusionButton.disabled = true;
      return;
  }

  if (warpStability >= 75 && energyEfficiency >= 75) {
    initiateFusionButton.disabled = false;
    const placeholder = fusionOutputContent.querySelector('.placeholder');
    if (placeholder) {
      placeholder.textContent = 'Component is fusion-compatible. Ready to initiate simulation.';
    }
  } else {
    initiateFusionButton.disabled = true;
    const placeholder = fusionOutputContent.querySelector('.placeholder');
    if (placeholder) {
      placeholder.textContent = 'Component not suitable for fusion. Requires Warp Stability and Energy Efficiency >= 75%.';
    }
  }
}

function buildFusionPrompt(): string {
  return `
    You are a fusion reactor simulation AI. A new subspace drive component has been designed and is now being tested for its potential in a cold fusion reactor.

    **Component Full Specification:**
    ${lastComponentSpec}

    **Analysis Task:**
    Based on the component's detailed specifications, especially its operational principles and materials, provide a simulation report.
    1.  **Plasma Interaction:** Describe how the component's unique properties (e.g., its handling of spacetime, gravitons, or negative energy) would interact with and contain a high-energy fusion plasma.
    2.  **Reactor Performance:** Estimate the potential power output in Megawatts (MW) and the overall stability of the reaction.
    3.  **Final Verdict:** Conclude with a single-word verdict: 'STABLE', 'UNSTABLE', or 'OPTIMAL'.

    Format the response as a concise, technical report using Markdown.
  `;
}

async function handleFusionSimulation() {
  const prompt = buildFusionPrompt();
  if (!prompt) return;

  initiateFusionButton.disabled = true;
  synthesizeButton.disabled = true;
  fusionCore.classList.add('active');
  fusionStatus.textContent = 'SIMULATING';
  fusionPower.textContent = '... MW';
  fusionOutputContent.innerHTML = '';
  const placeholder = document.createElement('p');
  placeholder.className = 'placeholder';
  placeholder.textContent = 'Initiating plasma containment... Running quantum analysis...';
  fusionOutputContent.appendChild(placeholder);

  try {
    const stream = await ai.models.generateContentStream({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: `You are a sophisticated AI that simulates the performance of theoretical components within a cold fusion reactor. Provide a detailed, scientific, and creative analysis based on the provided component data. Your tone should be that of a lead research engineer reporting findings. Format output using Markdown.`,
      },
    });

    let fullResponse = '';
    placeholder.remove();

    for await (const chunk of stream) {
      fullResponse += chunk.text;
      const renderedHtml = md.render(fullResponse + '▋');
      setElementInnerHtml(fusionOutputContent, sanitizeHtml(renderedHtml));
    }

    const finalHtml = md.render(fullResponse);
    setElementInnerHtml(fusionOutputContent, sanitizeHtml(finalHtml));

    // Update status from response
    if (fullResponse.includes('OPTIMAL')) {
      fusionStatus.textContent = 'OPTIMAL';
    } else if (fullResponse.includes('STABLE')) {
      fusionStatus.textContent = 'STABLE';
    } else {
      fusionStatus.textContent = 'UNSTABLE';
    }
    const powerMatch = fullResponse.match(/(\d+(\.\d+)?)\s*MW/);
    if(powerMatch) {
      fusionPower.textContent = `${powerMatch[1]} MW`;
    } else {
      fusionPower.textContent = 'N/A';
    }


  } catch (error) {
    console.error('Fusion sim failed:', error);
    const errorHtml = md.render('**Simulation Failed!**\n\nContainment field collapsed. Check component specifications.');
    setElementInnerHtml(fusionOutputContent, sanitizeHtml(errorHtml));
    fusionStatus.textContent = 'ERROR';
  } finally {
    fusionCore.classList.remove('active');
    synthesizeButton.disabled = false;
    // Keep fusion button disabled until a new compatible component is made
  }
}

// --- Event Listeners ---
synthesizeButton.addEventListener('click', handleSynthesize);
visualizeButton.addEventListener('click', handleVisualize);
initiateFusionButton.addEventListener('click', handleFusionSimulation);

// --- App Start ---
initializeUI();
initializeAI();

export {};

